-- WARNING: This schema is for context only and is not meant to be run.
-- Table order and constraints may not be valid for execution.

CREATE TABLE public.admin_settings (
  setting_key text NOT NULL,
  setting_value jsonb NOT NULL DEFAULT '{}'::jsonb,
  updated_by uuid,
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT admin_settings_pkey PRIMARY KEY (setting_key),
  CONSTRAINT admin_settings_updated_by_fkey FOREIGN KEY (updated_by) REFERENCES public.customers(customer_id)
);
CREATE TABLE public.anon_sessions (
  anon_session_id uuid NOT NULL DEFAULT gen_random_uuid(),
  ip_address text,
  last_seen_at timestamp with time zone NOT NULL DEFAULT now(),
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT anon_sessions_pkey PRIMARY KEY (anon_session_id)
);
CREATE TABLE public.blog_post_likes (
  like_id uuid NOT NULL DEFAULT gen_random_uuid(),
  post_id uuid NOT NULL,
  actor_key text NOT NULL,
  owner_type text NOT NULL CHECK (owner_type = ANY (ARRAY['anon'::text, 'customer'::text])),
  customer_id uuid,
  anon_session_id uuid,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT blog_post_likes_pkey PRIMARY KEY (like_id),
  CONSTRAINT blog_post_likes_post_id_fkey FOREIGN KEY (post_id) REFERENCES public.blog_posts(post_id),
  CONSTRAINT blog_post_likes_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES public.customers(customer_id),
  CONSTRAINT blog_post_likes_anon_session_id_fkey FOREIGN KEY (anon_session_id) REFERENCES public.anon_sessions(anon_session_id)
);
CREATE TABLE public.blog_posts (
  post_id uuid NOT NULL DEFAULT gen_random_uuid(),
  title text NOT NULL CHECK (char_length(TRIM(BOTH FROM title)) > 0),
  body text NOT NULL DEFAULT ''::text,
  image_storage_paths ARRAY NOT NULL DEFAULT '{}'::text[],
  links jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(links) = 'array'::text),
  status text NOT NULL DEFAULT 'draft'::text CHECK (status = ANY (ARRAY['draft'::text, 'published'::text, 'hidden'::text, 'archived'::text])),
  like_count integer NOT NULL DEFAULT 0,
  created_by_customer_id uuid,
  updated_by_customer_id uuid,
  published_at timestamp with time zone,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT blog_posts_pkey PRIMARY KEY (post_id),
  CONSTRAINT blog_posts_created_by_customer_id_fkey FOREIGN KEY (created_by_customer_id) REFERENCES public.customers(customer_id),
  CONSTRAINT blog_posts_updated_by_customer_id_fkey FOREIGN KEY (updated_by_customer_id) REFERENCES public.customers(customer_id)
);
CREATE TABLE public.cart_items (
  cart_item_id uuid NOT NULL DEFAULT gen_random_uuid(),
  owner_type USER-DEFINED NOT NULL,
  anon_session_id uuid,
  customer_id uuid,
  product_type USER-DEFINED NOT NULL,
  quantity integer NOT NULL DEFAULT 1,
  payment_id uuid,
  price_at_purchase numeric,
  final_job_id uuid,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  order_id uuid,
  status USER-DEFINED NOT NULL DEFAULT 'draft'::cart_item_status,
  creation_id uuid,
  CONSTRAINT cart_items_pkey PRIMARY KEY (cart_item_id),
  CONSTRAINT orders_anon_session_id_fkey FOREIGN KEY (anon_session_id) REFERENCES public.anon_sessions(anon_session_id),
  CONSTRAINT orders_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES public.customers(customer_id),
  CONSTRAINT orders_payment_id_fkey FOREIGN KEY (payment_id) REFERENCES public.payments(payment_id),
  CONSTRAINT fk_final_job FOREIGN KEY (final_job_id) REFERENCES public.jobs(job_id),
  CONSTRAINT orders_checkout_id_fkey FOREIGN KEY (order_id) REFERENCES public.orders(order_id),
  CONSTRAINT cart_items_creation_id_fkey FOREIGN KEY (creation_id) REFERENCES public.creations(creation_id)
);
CREATE TABLE public.creations (
  creation_id uuid NOT NULL DEFAULT gen_random_uuid(),
  anon_session_id uuid,
  template_id text NOT NULL,
  customize_snapshot jsonb NOT NULL,
  preview_job_id uuid,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  customer_id uuid,
  owner_type USER-DEFINED,
  is_archived boolean NOT NULL DEFAULT false,
  deleted_at timestamp with time zone,
  CONSTRAINT creations_pkey PRIMARY KEY (creation_id),
  CONSTRAINT creations_anon_session_id_fkey FOREIGN KEY (anon_session_id) REFERENCES public.anon_sessions(anon_session_id),
  CONSTRAINT creations_template_id_fkey FOREIGN KEY (template_id) REFERENCES public.templates(template_id),
  CONSTRAINT creations_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES public.customers(customer_id)
);
CREATE TABLE public.creator_promo_codes (
  creator_promo_code_id uuid NOT NULL DEFAULT gen_random_uuid(),
  owner_customer_id uuid NOT NULL,
  owner_email text,
  raw_input text NOT NULL,
  code text NOT NULL,
  suffix text NOT NULL DEFAULT '-YMI'::text,
  discount_amount_usd numeric NOT NULL DEFAULT 5,
  first_order_only boolean NOT NULL DEFAULT true,
  status text NOT NULL DEFAULT 'active'::text CHECK (status = ANY (ARRAY['active'::text, 'disabled'::text, 'archived'::text])),
  usage_count integer NOT NULL DEFAULT 0,
  paid_usage_count integer NOT NULL DEFAULT 0,
  attributed_order_amount_usd numeric NOT NULL DEFAULT 0,
  attributed_discount_amount_usd numeric NOT NULL DEFAULT 0,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT creator_promo_codes_pkey PRIMARY KEY (creator_promo_code_id),
  CONSTRAINT creator_promo_codes_owner_customer_id_fkey FOREIGN KEY (owner_customer_id) REFERENCES public.customers(customer_id)
);
CREATE TABLE public.creator_promo_redemptions (
  creator_promo_redemption_id uuid NOT NULL DEFAULT gen_random_uuid(),
  creator_promo_code_id uuid NOT NULL,
  order_id uuid NOT NULL,
  referred_customer_id uuid,
  referred_email text,
  discount_amount_usd numeric NOT NULL DEFAULT 5,
  status text NOT NULL DEFAULT 'applied'::text CHECK (status = ANY (ARRAY['applied'::text, 'paid'::text, 'cancelled'::text])),
  paid_order_amount_usd numeric,
  paid_at timestamp with time zone,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT creator_promo_redemptions_pkey PRIMARY KEY (creator_promo_redemption_id),
  CONSTRAINT creator_promo_redemptions_order_id_fkey FOREIGN KEY (order_id) REFERENCES public.orders(order_id),
  CONSTRAINT creator_promo_redemptions_creator_promo_code_id_fkey FOREIGN KEY (creator_promo_code_id) REFERENCES public.creator_promo_codes(creator_promo_code_id),
  CONSTRAINT creator_promo_redemptions_referred_customer_id_fkey FOREIGN KEY (referred_customer_id) REFERENCES public.customers(customer_id)
);
CREATE TABLE public.customer_coupon_codes (
  coupon_code_id uuid NOT NULL DEFAULT gen_random_uuid(),
  customer_id uuid NOT NULL,
  source_type text NOT NULL CHECK (source_type = 'referral_reward'::text),
  source_order_id uuid,
  source_referral_code_id uuid,
  code text NOT NULL,
  amount_usd numeric NOT NULL DEFAULT 5,
  status text NOT NULL DEFAULT 'active'::text CHECK (status = ANY (ARRAY['active'::text, 'redeemed'::text, 'expired'::text, 'cancelled'::text])),
  expires_at timestamp with time zone NOT NULL,
  redeemed_order_id uuid,
  redeemed_at timestamp with time zone,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT customer_coupon_codes_pkey PRIMARY KEY (coupon_code_id),
  CONSTRAINT customer_coupon_codes_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES public.customers(customer_id),
  CONSTRAINT customer_coupon_codes_source_order_id_fkey FOREIGN KEY (source_order_id) REFERENCES public.orders(order_id),
  CONSTRAINT customer_coupon_codes_source_referral_code_id_fkey FOREIGN KEY (source_referral_code_id) REFERENCES public.referral_codes(referral_code_id),
  CONSTRAINT customer_coupon_codes_redeemed_order_id_fkey FOREIGN KEY (redeemed_order_id) REFERENCES public.orders(order_id)
);
CREATE TABLE public.customers (
  customer_id uuid NOT NULL DEFAULT gen_random_uuid(),
  email text NOT NULL UNIQUE,
  auth_user_id uuid UNIQUE,
  display_name text,
  is_guest boolean NOT NULL DEFAULT true,
  stripe_customer_id text,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  avatar_asset_id uuid,
  avatar_storage_path text,
  role text NOT NULL DEFAULT 'customer'::text CHECK (role = ANY (ARRAY['customer'::text, 'admin'::text])),
  cookie_consent jsonb,
  cookie_consent_version text,
  cookie_consent_updated_at timestamp with time zone,
  CONSTRAINT customers_pkey PRIMARY KEY (customer_id),
  CONSTRAINT customers_auth_user_id_fkey FOREIGN KEY (auth_user_id) REFERENCES auth.users(id),
  CONSTRAINT customers_avatar_asset_id_fkey FOREIGN KEY (avatar_asset_id) REFERENCES public.user_assets(asset_id)
);
CREATE TABLE public.favourites (
  favourite_id uuid NOT NULL DEFAULT gen_random_uuid(),
  owner_type USER-DEFINED NOT NULL,
  anon_session_id uuid,
  customer_id uuid,
  template_id text NOT NULL,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT favourites_pkey PRIMARY KEY (favourite_id),
  CONSTRAINT favourites_anon_session_id_fkey FOREIGN KEY (anon_session_id) REFERENCES public.anon_sessions(anon_session_id),
  CONSTRAINT favourites_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES public.customers(customer_id),
  CONSTRAINT favourites_template_id_fkey FOREIGN KEY (template_id) REFERENCES public.templates(template_id)
);
CREATE TABLE public.final_job_pages (
  final_job_page_id uuid NOT NULL DEFAULT gen_random_uuid(),
  final_job_id uuid NOT NULL,
  page_index integer NOT NULL CHECK (page_index >= 0),
  status text NOT NULL DEFAULT 'queued'::text CHECK (status = ANY (ARRAY['queued'::text, 'processing'::text, 'pending_review'::text, 'approved'::text, 'needs_fix'::text, 'rerunning'::text, 'replaced'::text, 'failed'::text])),
  ai_output_path text,
  manual_output_path text,
  approved_output_path text,
  approved_source text CHECK (approved_source IS NULL OR (approved_source = ANY (ARRAY['ai'::text, 'manual'::text]))),
  provider_request_id text,
  review_note text,
  reviewed_by uuid,
  reviewed_at timestamp with time zone,
  attempt_count integer NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  error_message text,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  print_output_path text,
  print_status text NOT NULL DEFAULT 'waiting_upload'::text CHECK (print_status = ANY (ARRAY['locked'::text, 'waiting_upload'::text, 'completed'::text])),
  review_intent_id uuid,
  review_intent_type text CHECK (review_intent_type IS NULL OR (review_intent_type = ANY (ARRAY['approve'::text, 'needs_fix'::text, 'approve_all'::text]))),
  review_intent_at timestamp with time zone,
  CONSTRAINT final_job_pages_pkey PRIMARY KEY (final_job_page_id),
  CONSTRAINT final_job_pages_final_job_id_fkey FOREIGN KEY (final_job_id) REFERENCES public.final_jobs(final_job_id),
  CONSTRAINT final_job_pages_reviewed_by_fkey FOREIGN KEY (reviewed_by) REFERENCES public.customers(customer_id)
);
CREATE TABLE public.final_jobs (
  final_job_id uuid NOT NULL DEFAULT gen_random_uuid(),
  job_id uuid NOT NULL UNIQUE,
  order_id uuid NOT NULL,
  cart_item_id uuid NOT NULL UNIQUE,
  creation_id uuid,
  template_id text NOT NULL,
  status text NOT NULL DEFAULT 'queued'::text CHECK (status = ANY (ARRAY['queued'::text, 'processing'::text, 'review_pending'::text, 'needs_fix'::text, 'releasing'::text, 'completed'::text, 'failed'::text])),
  review_status text NOT NULL DEFAULT 'pending'::text CHECK (review_status = ANY (ARRAY['pending'::text, 'in_review'::text, 'approved'::text, 'needs_fix'::text, 'released'::text])),
  total_pages integer NOT NULL DEFAULT 15 CHECK (total_pages > 0),
  approved_pages integer NOT NULL DEFAULT 0 CHECK (approved_pages >= 0),
  release_mode text NOT NULL DEFAULT 'manual'::text CHECK (release_mode = ANY (ARRAY['manual'::text, 'job_auto'::text, 'story_auto'::text, 'global_auto'::text])),
  pdf_path text,
  released_at timestamp with time zone,
  email_sent_at timestamp with time zone,
  error_message text,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  print_status text NOT NULL DEFAULT 'locked'::text CHECK (print_status = ANY (ARRAY['locked'::text, 'pending'::text, 'in_review'::text, 'ready'::text, 'released'::text])),
  print_completed_pages integer NOT NULL DEFAULT 0 CHECK (print_completed_pages >= 0),
  print_released_at timestamp with time zone,
  print_package_path text,
  CONSTRAINT final_jobs_pkey PRIMARY KEY (final_job_id),
  CONSTRAINT final_jobs_job_id_fkey FOREIGN KEY (job_id) REFERENCES public.jobs(job_id),
  CONSTRAINT final_jobs_order_id_fkey FOREIGN KEY (order_id) REFERENCES public.orders(order_id),
  CONSTRAINT final_jobs_cart_item_id_fkey FOREIGN KEY (cart_item_id) REFERENCES public.cart_items(cart_item_id),
  CONSTRAINT final_jobs_creation_id_fkey FOREIGN KEY (creation_id) REFERENCES public.creations(creation_id),
  CONSTRAINT final_jobs_template_id_fkey FOREIGN KEY (template_id) REFERENCES public.templates(template_id)
);
CREATE TABLE public.jobs (
  job_id uuid NOT NULL DEFAULT gen_random_uuid(),
  owner_type USER-DEFINED NOT NULL,
  anon_session_id uuid,
  customer_id uuid,
  cart_item_id uuid,
  template_id text NOT NULL,
  job_type USER-DEFINED NOT NULL,
  status USER-DEFINED NOT NULL DEFAULT 'queued'::job_status,
  progress integer NOT NULL DEFAULT 0,
  input_snapshot jsonb NOT NULL,
  output_assets jsonb,
  error_message text,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  creation_id uuid,
  story_language text NOT NULL DEFAULT 'English'::text CHECK (story_language = ANY (ARRAY['English'::text, 'Traditional Chinese'::text, 'Spanish'::text])),
  selected_book_type text NOT NULL DEFAULT 'Classic'::text CHECK (selected_book_type = ANY (ARRAY['Cloud Explorer'::text, 'Classic'::text, 'Immersive'::text, 'Signature Voice'::text])),
  provider_runs jsonb NOT NULL DEFAULT '{}'::jsonb,
  render_runs jsonb NOT NULL DEFAULT '{}'::jsonb,
  CONSTRAINT jobs_pkey PRIMARY KEY (job_id),
  CONSTRAINT jobs_anon_session_id_fkey FOREIGN KEY (anon_session_id) REFERENCES public.anon_sessions(anon_session_id),
  CONSTRAINT jobs_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES public.customers(customer_id),
  CONSTRAINT jobs_order_id_fkey FOREIGN KEY (cart_item_id) REFERENCES public.cart_items(cart_item_id),
  CONSTRAINT jobs_template_id_fkey FOREIGN KEY (template_id) REFERENCES public.templates(template_id),
  CONSTRAINT jobs_creation_id_fkey FOREIGN KEY (creation_id) REFERENCES public.creations(creation_id)
);
CREATE TABLE public.kol_collaboration_leads (
  lead_id uuid NOT NULL DEFAULT gen_random_uuid(),
  customer_id uuid,
  nickname text NOT NULL,
  gender text NOT NULL CHECK (gender = ANY (ARRAY['female'::text, 'male'::text, 'non_binary'::text, 'prefer_not_to_say'::text])),
  email text,
  phone text,
  whatsapp_or_wechat text,
  instagram text,
  tiktok text,
  youtube text,
  xiaohongshu text,
  notes text,
  review_status text NOT NULL DEFAULT 'new'::text CHECK (review_status = ANY (ARRAY['new'::text, 'contacted'::text, 'closed'::text, 'archived'::text])),
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT kol_collaboration_leads_pkey PRIMARY KEY (lead_id),
  CONSTRAINT kol_collaboration_leads_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES public.customers(customer_id)
);
CREATE TABLE public.newsletter_subscribers (
  subscriber_id uuid NOT NULL DEFAULT gen_random_uuid(),
  email text NOT NULL UNIQUE,
  customer_id uuid,
  anon_session_id uuid,
  source text NOT NULL DEFAULT 'footer'::text,
  status text NOT NULL DEFAULT 'active'::text CHECK (status = ANY (ARRAY['active'::text, 'unsubscribed'::text, 'bounced'::text])),
  subscribed_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT newsletter_subscribers_pkey PRIMARY KEY (subscriber_id),
  CONSTRAINT newsletter_subscribers_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES public.customers(customer_id),
  CONSTRAINT newsletter_subscribers_anon_session_id_fkey FOREIGN KEY (anon_session_id) REFERENCES public.anon_sessions(anon_session_id)
);
CREATE TABLE public.order_reminder_logs (
  reminder_id uuid NOT NULL DEFAULT gen_random_uuid(),
  order_id uuid NOT NULL,
  customer_id uuid,
  reminder_type text NOT NULL DEFAULT 'unpaid'::text,
  sent_to_email text NOT NULL,
  sent_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT order_reminder_logs_pkey PRIMARY KEY (reminder_id),
  CONSTRAINT order_reminder_logs_order_id_fkey FOREIGN KEY (order_id) REFERENCES public.orders(order_id),
  CONSTRAINT order_reminder_logs_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES public.customers(customer_id)
);
CREATE TABLE public.order_reminder_schedules (
  order_id uuid NOT NULL,
  customer_id uuid,
  next_send_at timestamp with time zone NOT NULL,
  repeat_every_days integer NOT NULL DEFAULT 3,
  active boolean NOT NULL DEFAULT true,
  last_sent_at timestamp with time zone,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT order_reminder_schedules_pkey PRIMARY KEY (order_id),
  CONSTRAINT order_reminder_schedules_order_id_fkey FOREIGN KEY (order_id) REFERENCES public.orders(order_id),
  CONSTRAINT order_reminder_schedules_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES public.customers(customer_id)
);
CREATE TABLE public.order_reviews (
  review_id uuid NOT NULL DEFAULT gen_random_uuid(),
  order_id uuid NOT NULL UNIQUE,
  customer_id uuid,
  template_id text NOT NULL,
  rating integer NOT NULL CHECK (rating >= 1 AND rating <= 5),
  comment text,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT order_reviews_pkey PRIMARY KEY (review_id),
  CONSTRAINT order_reviews_order_id_fkey FOREIGN KEY (order_id) REFERENCES public.orders(order_id),
  CONSTRAINT order_reviews_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES public.customers(customer_id),
  CONSTRAINT order_reviews_template_id_fkey FOREIGN KEY (template_id) REFERENCES public.templates(template_id)
);
CREATE TABLE public.orders (
  order_id uuid NOT NULL DEFAULT gen_random_uuid(),
  payment_id uuid UNIQUE,
  customer_id uuid,
  email text,
  shipping_address jsonb NOT NULL,
  billing_address jsonb,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  order_status USER-DEFINED NOT NULL DEFAULT 'unpaid'::order_status_enum,
  display_id text,
  checkout_currency text NOT NULL DEFAULT 'USD'::text CHECK (checkout_currency = ANY (ARRAY['USD'::text, 'EUR'::text, 'GBP'::text, 'JPY'::text, 'AUD'::text, 'CAD'::text, 'SGD'::text, 'HKD'::text, 'KRW'::text, 'CNY'::text])),
  applied_discount_code text,
  applied_discount_type text CHECK (applied_discount_type IS NULL OR (applied_discount_type = ANY (ARRAY['referral'::text, 'coupon'::text, 'creator_promo'::text]))),
  applied_referral_code_id uuid,
  applied_coupon_code_id uuid,
  discount_amount_usd numeric NOT NULL DEFAULT 0,
  shipping_amount_usd numeric NOT NULL DEFAULT 0,
  shipping_rate_snapshot jsonb,
  shipping_method text,
  shipping_zone_code text,
  CONSTRAINT orders_pkey PRIMARY KEY (order_id),
  CONSTRAINT checkouts_payment_id_fkey FOREIGN KEY (payment_id) REFERENCES public.payments(payment_id),
  CONSTRAINT checkouts_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES public.customers(customer_id),
  CONSTRAINT orders_applied_referral_code_id_fkey FOREIGN KEY (applied_referral_code_id) REFERENCES public.referral_codes(referral_code_id),
  CONSTRAINT orders_applied_coupon_code_id_fkey FOREIGN KEY (applied_coupon_code_id) REFERENCES public.customer_coupon_codes(coupon_code_id)
);
CREATE TABLE public.payments (
  payment_id uuid NOT NULL DEFAULT gen_random_uuid(),
  customer_id uuid NOT NULL,
  amount numeric NOT NULL,
  currency text NOT NULL DEFAULT 'usd'::text,
  provider text NOT NULL,
  status text NOT NULL,
  provider_ref text,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  order_id uuid,
  CONSTRAINT payments_pkey PRIMARY KEY (payment_id),
  CONSTRAINT payments_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES public.customers(customer_id),
  CONSTRAINT payments_checkout_id_fkey FOREIGN KEY (order_id) REFERENCES public.orders(order_id)
);
CREATE TABLE public.preview_share_links (
  preview_share_id uuid NOT NULL DEFAULT gen_random_uuid(),
  creation_id uuid NOT NULL,
  preview_job_id uuid NOT NULL,
  template_id text,
  owner_type text NOT NULL CHECK (owner_type = ANY (ARRAY['anon'::text, 'customer'::text])),
  anon_session_id text,
  customer_id uuid,
  share_token text NOT NULL,
  cover_bucket text NOT NULL DEFAULT 'raw-private'::text,
  cover_storage_path text NOT NULL,
  expires_at timestamp with time zone,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT preview_share_links_pkey PRIMARY KEY (preview_share_id),
  CONSTRAINT preview_share_links_template_id_fkey FOREIGN KEY (template_id) REFERENCES public.templates(template_id),
  CONSTRAINT preview_share_links_creation_id_fkey FOREIGN KEY (creation_id) REFERENCES public.creations(creation_id),
  CONSTRAINT preview_share_links_preview_job_id_fkey FOREIGN KEY (preview_job_id) REFERENCES public.jobs(job_id),
  CONSTRAINT preview_share_links_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES public.customers(customer_id)
);
CREATE TABLE public.referral_codes (
  referral_code_id uuid NOT NULL DEFAULT gen_random_uuid(),
  order_id uuid NOT NULL,
  inviter_customer_id uuid,
  inviter_email text NOT NULL,
  code text NOT NULL,
  template_id text,
  cover_bucket text NOT NULL DEFAULT 'raw-private'::text,
  cover_storage_path text NOT NULL,
  discount_amount_usd numeric NOT NULL DEFAULT 5,
  reward_amount_usd numeric NOT NULL DEFAULT 5,
  status text NOT NULL DEFAULT 'active'::text CHECK (status = ANY (ARRAY['active'::text, 'reserved'::text, 'consumed'::text, 'cancelled'::text, 'expired'::text])),
  expires_at timestamp with time zone NOT NULL,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT referral_codes_pkey PRIMARY KEY (referral_code_id),
  CONSTRAINT referral_codes_order_id_fkey FOREIGN KEY (order_id) REFERENCES public.orders(order_id),
  CONSTRAINT referral_codes_inviter_customer_id_fkey FOREIGN KEY (inviter_customer_id) REFERENCES public.customers(customer_id),
  CONSTRAINT referral_codes_template_id_fkey FOREIGN KEY (template_id) REFERENCES public.templates(template_id)
);
CREATE TABLE public.referral_redemptions (
  referral_redemption_id uuid NOT NULL DEFAULT gen_random_uuid(),
  referral_code_id uuid NOT NULL,
  referred_order_id uuid NOT NULL,
  referred_customer_id uuid,
  referred_email text,
  reward_coupon_code_id uuid,
  discount_amount_usd numeric NOT NULL DEFAULT 5,
  status text NOT NULL DEFAULT 'applied'::text CHECK (status = ANY (ARRAY['applied'::text, 'paid'::text, 'cancelled'::text])),
  rewarded_at timestamp with time zone,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT referral_redemptions_pkey PRIMARY KEY (referral_redemption_id),
  CONSTRAINT referral_redemptions_referral_code_id_fkey FOREIGN KEY (referral_code_id) REFERENCES public.referral_codes(referral_code_id),
  CONSTRAINT referral_redemptions_referred_order_id_fkey FOREIGN KEY (referred_order_id) REFERENCES public.orders(order_id),
  CONSTRAINT referral_redemptions_referred_customer_id_fkey FOREIGN KEY (referred_customer_id) REFERENCES public.customers(customer_id),
  CONSTRAINT referral_redemptions_reward_coupon_code_id_fkey FOREIGN KEY (reward_coupon_code_id) REFERENCES public.customer_coupon_codes(coupon_code_id)
);
CREATE TABLE public.shipping_base_rates (
  rate_id uuid NOT NULL DEFAULT gen_random_uuid(),
  zone_code text NOT NULL,
  method_code text NOT NULL,
  weight_kg numeric NOT NULL DEFAULT 1.00,
  base_cost_hkd numeric NOT NULL CHECK (base_cost_hkd >= 0::numeric),
  source_cost_text text,
  source_channel text,
  source_note text,
  enabled boolean NOT NULL DEFAULT true,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT shipping_base_rates_pkey PRIMARY KEY (rate_id),
  CONSTRAINT shipping_base_rates_zone_code_fkey FOREIGN KEY (zone_code) REFERENCES public.shipping_zones(zone_code),
  CONSTRAINT shipping_base_rates_method_code_fkey FOREIGN KEY (method_code) REFERENCES public.shipping_methods(method_code)
);
CREATE TABLE public.shipping_countries (
  country_code text NOT NULL CHECK (country_code = upper(country_code) AND length(country_code) >= 2 AND length(country_code) <= 3),
  display_name_en text NOT NULL,
  display_name_cn_s text,
  display_name_cn_t text,
  display_name_ja text,
  display_name_es text,
  display_name_ko text,
  flag_url text,
  flag_emoji text,
  enabled boolean NOT NULL DEFAULT true,
  sort_order integer NOT NULL DEFAULT 9999,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT shipping_countries_pkey PRIMARY KEY (country_code)
);
CREATE TABLE public.shipping_country_method_support (
  country_code text NOT NULL CHECK (country_code = upper(country_code) AND length(country_code) >= 2 AND length(country_code) <= 3),
  method_code text NOT NULL,
  enabled boolean NOT NULL DEFAULT true,
  source_group text,
  source_note text,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT shipping_country_method_support_pkey PRIMARY KEY (country_code, method_code),
  CONSTRAINT shipping_country_method_support_method_code_fkey FOREIGN KEY (method_code) REFERENCES public.shipping_methods(method_code)
);
CREATE TABLE public.shipping_methods (
  method_code text NOT NULL,
  display_name text NOT NULL,
  description text,
  speed_label text,
  sort_order integer NOT NULL DEFAULT 0,
  enabled boolean NOT NULL DEFAULT true,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT shipping_methods_pkey PRIMARY KEY (method_code)
);
CREATE TABLE public.shipping_pricing_rules (
  rule_id uuid NOT NULL DEFAULT gen_random_uuid(),
  rule_name text NOT NULL,
  method_code text,
  zone_code text,
  fuel_surcharge_percent numeric NOT NULL DEFAULT 0,
  handling_fee_hkd numeric NOT NULL DEFAULT 0,
  margin_percent numeric NOT NULL DEFAULT 0,
  discount_percent numeric NOT NULL DEFAULT 0,
  fx_adjustment_percent numeric NOT NULL DEFAULT 0,
  min_charge_hkd numeric NOT NULL DEFAULT 0,
  priority integer NOT NULL DEFAULT 0,
  enabled boolean NOT NULL DEFAULT true,
  valid_from timestamp with time zone,
  valid_to timestamp with time zone,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT shipping_pricing_rules_pkey PRIMARY KEY (rule_id),
  CONSTRAINT shipping_pricing_rules_method_code_fkey FOREIGN KEY (method_code) REFERENCES public.shipping_methods(method_code),
  CONSTRAINT shipping_pricing_rules_zone_code_fkey FOREIGN KEY (zone_code) REFERENCES public.shipping_zones(zone_code)
);
CREATE TABLE public.shipping_zone_countries (
  zone_country_id uuid NOT NULL DEFAULT gen_random_uuid(),
  zone_code text NOT NULL,
  country_code text NOT NULL CHECK (country_code = upper(country_code) AND length(country_code) >= 2 AND length(country_code) <= 3),
  region_key text,
  region_label text,
  country_label text,
  priority integer NOT NULL DEFAULT 0,
  enabled boolean NOT NULL DEFAULT true,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT shipping_zone_countries_pkey PRIMARY KEY (zone_country_id),
  CONSTRAINT shipping_zone_countries_zone_code_fkey FOREIGN KEY (zone_code) REFERENCES public.shipping_zones(zone_code)
);
CREATE TABLE public.shipping_zones (
  zone_code text NOT NULL,
  display_name text NOT NULL,
  source_note text,
  enabled boolean NOT NULL DEFAULT true,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT shipping_zones_pkey PRIMARY KEY (zone_code)
);
CREATE TABLE public.support_questions (
  question_id uuid NOT NULL DEFAULT gen_random_uuid(),
  customer_id uuid NOT NULL,
  email text NOT NULL,
  display_name text,
  question text NOT NULL,
  status text NOT NULL DEFAULT 'new'::text CHECK (status = ANY (ARRAY['new'::text, 'replied'::text, 'closed'::text, 'archived'::text])),
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  updated_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT support_questions_pkey PRIMARY KEY (question_id),
  CONSTRAINT support_questions_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES public.customers(customer_id)
);
CREATE TABLE public.templates (
  template_id text NOT NULL,
  template_uuid uuid DEFAULT gen_random_uuid() UNIQUE,
  name text NOT NULL,
  description text,
  book_type USER-DEFINED NOT NULL DEFAULT 'ebook'::product_type,
  cover_image_path text NOT NULL,
  default_config_path text,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  story_type text,
  age_group text NOT NULL DEFAULT 'ages_2_plus'::text CHECK (age_group = ANY (ARRAY['ages_2_plus'::text, 'ages_6_plus'::text])),
  display_order integer,
  price_cents numeric(10,2) NOT NULL DEFAULT 24.99,
  target_gender text NOT NULL DEFAULT 'Neutral'::text,
  home_sections ARRAY NOT NULL DEFAULT '{}'::text[],
  is_discount boolean NOT NULL DEFAULT false,
  normalized_cover_image_path text,
  showcase_image_paths ARRAY NOT NULL DEFAULT '{}'::text[],
  is_brand_new boolean NOT NULL DEFAULT false,
  is_for_boys boolean NOT NULL DEFAULT false,
  is_for_girls boolean NOT NULL DEFAULT false,
  compare_at_price_cents numeric(10,2),
  discount_percent integer,
  final_auto_release_enabled boolean NOT NULL DEFAULT false,
  inner_description text,
  is_coming_soon boolean NOT NULL DEFAULT false,
  CONSTRAINT templates_pkey PRIMARY KEY (template_id)
);
CREATE TABLE public.user_assets (
  asset_id uuid NOT NULL DEFAULT gen_random_uuid(),
  owner_type USER-DEFINED NOT NULL,
  anon_session_id uuid,
  customer_id uuid,
  asset_type USER-DEFINED NOT NULL,
  storage_path text,
  metadata jsonb DEFAULT '{}'::jsonb,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT user_assets_pkey PRIMARY KEY (asset_id),
  CONSTRAINT user_assets_anon_session_id_fkey FOREIGN KEY (anon_session_id) REFERENCES public.anon_sessions(anon_session_id),
  CONSTRAINT user_assets_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES public.customers(customer_id)
);
CREATE TABLE public.verification_codes (
  verification_id uuid NOT NULL DEFAULT gen_random_uuid(),
  email text NOT NULL,
  code text NOT NULL,
  expires_at timestamp with time zone NOT NULL,
  created_at timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT verification_codes_pkey PRIMARY KEY (verification_id)
);
